--[[ generated by midnight from midnight/resurrect/init.mn, edit that instead ]] local _MODULE = {} _MODULE.db = nil
_MODULE.active_session = nil
_MODULE.augroup_name = "resurrect"
---@class config
_MODULE.config = {
status_icon = "🪦", 
status_icon_active = "📓", 
add_command = true, 
always_choose = false, 
quiet = false, 
db_path = vim.fn.stdpath("data") .. "/resurrect.db", 
ignore = {"^term://", "^fugitive://", "^snacks://"}, 

debug = false
}


local branch_watcher = nil

local function ignored(path)
  return vim.iter(_MODULE.config.ignore):any(function(m) return path:match(m) ~= nil end)
end


local function busy()
  if _MODULE.active_session then
    vim.notify("current session (" .. tostring(_MODULE.active_session) .. ") still active", vim.log.levels.ERROR)
    return true
  end
  return false
end

--- buf's path if it's worth saving in a session: a listed, normal buffer w/ a
--- file name. Skips help, quickfix, terminals (ex. yazi), and plugin buffers
--- (oil://, fugitive://, ... or anything w/ a non '' buftype), plus
--- config.ignore. nil otherwise.
---@return string|nil
local function trackable(buf)
  if not vim.api.nvim_buf_is_valid(buf) or not vim.bo[buf].buflisted or vim.bo[buf].buftype ~= "" then
    return nil
  end
  local path = vim.api.nvim_buf_get_name(buf)
  if path == "" or path:match("^%a[%w+.-]*://") or ignored(path) then
    return nil
  end
  return path
end

local function add(ev)


  vim.schedule(function()
    local path = trackable(ev.buf)
    if path then _MODULE.db:add_file(path) end
  end)
end


local function focus(ev)
  local path = trackable(ev.buf)
  if path then _MODULE.db:set_last_file(path) end
end

--- after opening a session's files, switch to the one that had focus
local function restore_focus()
  local path = _MODULE.db:last_file()
  local __MIDNIGHT_TMP_1__ if path then __MIDNIGHT_TMP_1__ = (vim.fn.bufnr(path)) else __MIDNIGHT_TMP_1__ = -1 end local buf = __MIDNIGHT_TMP_1__
  if buf ~= -1 then vim.cmd.buffer(buf) end
end

local function del(ev)
  if ev.match ~= nil and ev.match ~= "" then
    _MODULE.db:del_file(ev.match)
  end
end

local function update_cursor(ev)
  local path = trackable(ev.buf)

  if not path or vim.api.nvim_win_get_buf(0) ~= ev.buf then
    return
  end
  local row, col local __MIDNIGHT_TMP_2__ = vim.api.nvim_win_get_cursor(0) row = __MIDNIGHT_TMP_2__[1] col = __MIDNIGHT_TMP_2__[2]
  _MODULE.db:update_file({path = path, row = row, col = col})
end

local function create_augroup()
  local id = vim.api.nvim_create_augroup(_MODULE.augroup_name, {})
  local autocmd = vim.api.nvim_create_autocmd
  autocmd("BufAdd", {group = id, callback = add})
  autocmd("BufDelete", {group = id, callback = del})

  autocmd({"BufLeave", "VimLeavePre"}, {group = id, callback = update_cursor})
  autocmd("BufEnter", {group = id, callback = focus})

  autocmd("BufWritePost", {group = id, callback = add})
end

local function set_status()
  do local __MIDNIGHT_TMP_3__ if _MODULE.active_session then __MIDNIGHT_TMP_3__ = 
      tostring(_MODULE.config.status_icon_active) .. " " .. tostring(_MODULE.active_session)
    elseif _MODULE.db:has_sessions() then __MIDNIGHT_TMP_3__ = 
      _MODULE.config.status_icon else __MIDNIGHT_TMP_3__ = 

      ""
    end vim.g.has_resurrect_sessions = __MIDNIGHT_TMP_3__ end
end

local function stop()
  if not _MODULE.active_session then
    vim.notify("no active session", vim.log.levels.WARN)
    return
  end
  if branch_watcher then
    branch_watcher:stop()
    branch_watcher:close()
    branch_watcher = nil
  end
  _MODULE.active_session = nil
  vim.api.nvim_del_augroup_by_name(_MODULE.augroup_name)
  set_status()
end

local function start(args)
  if busy() then return end
  local u = require("resurrect/util")
  local bufnums = vim.tbl_filter(vim.api.nvim_buf_is_loaded, vim.api.nvim_list_bufs())
  local session_name = args[1] or "default"
  if not _MODULE.db:new_session(session_name) then
    local dead_files = u.open_files(_MODULE.db.session.files)
    if #dead_files > 0 then
      vim.print(dead_files)
      vim.notify("there are " .. tostring(#dead_files) .. " missing files in session", vim.log.levels.WARN)
    end
  end


  for _, v in ipairs(bufnums) do
    local path = trackable(v)
    if path then
      if _MODULE.config.debug then
        vim.notify("adding new file " .. tostring(path) .. " to session", vim.log.levels.INFO)
      end
      _MODULE.db:add_file(path)
    end
  end
  restore_focus()

  _MODULE.active_session = session_name
  create_augroup()
  set_status()
end

local function start_git(args)
  if busy() then return end
  local git = require("resurrect/git")

  local branch = git.current_branch()
  if not branch then
    vim.notify("not on a git branch (not a repo, or a detached HEAD)", vim.log.levels.WARN)
    return
  end
  local __MIDNIGHT_TMP_5__ if args[1] then __MIDNIGHT_TMP_5__ = tostring(branch) .. "@" .. tostring(args[1]) else __MIDNIGHT_TMP_5__ = branch end local session_name = __MIDNIGHT_TMP_5__

  start({session_name})


  branch_watcher = git.watch_branch(function(branches)
    local u = require("resurrect/util")
    local modified = u.modified_buffers()
    if #modified > 0 then
      local names = vim.tbl_map(function(b)
        local name = vim.api.nvim_buf_get_name(b)
        if name == "" then return "[No Name]" else return (vim.fn.fnamemodify(name, ":~:.")) end
      end, modified)
      vim.notify(
      "switching sessions discards unsaved changes in:\n" .. tostring(table.concat(names, "\n")), 
      vim.log.levels.WARN)

    end
    require("resurrect/ui").confirmation({
    prompt = "Git branch changed " .. tostring(branches.current) .. " -> " .. tostring(branches.new) .. ", switch? [y/N]", 
    callback = function(yes)
      if not yes then return end


      if _MODULE.active_session then stop() end
      u.close_files()
      start_git(args)
    end
    })
  end)
end

local function list()
  _MODULE.db:choose_session(function(name, s)
    local paths = vim.iter(s.files or {}):map(function(f) return f.path end):totable()
    vim.notify(tostring(name) .. ":\n" .. tostring(table.concat(paths, "\n")))
  end)
end

local function resurrect(fargs)
  if fargs.bang then
    stop()
    return
  end
  if busy() then return end
  local u = require("resurrect/util")
  _MODULE.db:load_session(function(session_name, files)
    local dead_files = u.open_files(files)
    if #dead_files > 0 then
      vim.notify(
      "there are " .. tostring(#dead_files) .. " missing files in session\n" .. tostring(vim.inspect(dead_files)), 
      vim.log.levels.WARN)

      _MODULE.db:prune_session_files(dead_files)
    end
    restore_focus()

    create_augroup()
    _MODULE.active_session = session_name
    set_status()
  end)
end

local function delete(id, name)
  if _MODULE.active_session == name then
    stop()
  end
  _MODULE.db:delete_session(id)
  set_status()
end

local function delete_session(arg)
  if #arg > 0 then
    local s = _MODULE.db:find_session(arg[1])
    if not s then
      vim.notify("no session '" .. tostring(arg[1]) .. "'", vim.log.levels.ERROR)
      return
    end
    if _MODULE.config.debug then
      vim.print(s)
    end
    delete(s.id, require("resurrect/util").session_shortname(s.name))
    return
  end
  _MODULE.db:choose_session(function(name, s)
    require("resurrect/ui").confirmation({
    prompt = "You want to delete session '" .. tostring(name) .. "'? [y/N]", 
    callback = function(yes)
      if yes then delete(s.id, name) end
    end
    })
  end)
end

function _MODULE.setup(opts) if opts == nil then opts = {} end
  _MODULE.config = vim.tbl_deep_extend("force", _MODULE.config, opts)


  _MODULE.db = require("resurrect/db").new(_MODULE.config)
  set_status()
  if _MODULE.db:has_sessions() and not _MODULE.config.quiet then
    vim.notify("there are resurrect sessions available")
  end

  if _MODULE.config.add_command then
    require("resurrect/util").user_command("Resurrect", {
    default = resurrect, 
    start = {cb = start, basic = true}, 
    git = {cb = start_git, basic = true}, 
    stop = stop, 
    list = list, 
    delete = {cb = delete_session, basic = true}
    })
  end
end
return _MODULE
